// Generate realistic sales data — randomized on each run so data looks fresh
const regions = ['East', 'West', 'North', 'South'];
const reps = ['Sarah Chen', 'Mike Johnson', 'Emily Davis', 'Robert Kim', 'Lisa Park'];
const categories = ['Widgets', 'Gadgets', 'Accessories', 'Software'];
const products = ['Widget Pro', 'Widget Lite', 'Gadget Max', 'Gadget Mini', 'AccessKit', 'SoftSuite'];
const customers = ['Acme Corp', 'TechStart Inc', 'Global Solutions', 'Prime Retail', 'FastGrow LLC', 'Apex Systems', 'Blue Ridge Co'];

const rows = [];
const now = new Date();

for (let i = 0; i < 100; i++) {
  const daysAgo = Math.floor(Math.random() * 90);
  const date = new Date(now.getTime() - daysAgo * 86400000);
  const qty = Math.floor(Math.random() * 20) + 1;
  const unitPrice = parseFloat((Math.random() * 200 + 10).toFixed(2));

  rows.push({
    order_id: `ORD-${date.toISOString().split('T')[0]}-${String(i).padStart(3,'0')}`,
    date: date.toISOString().split('T')[0],
    customer_name: customers[Math.floor(Math.random() * customers.length)],
    product: products[Math.floor(Math.random() * products.length)],
    category: categories[Math.floor(Math.random() * categories.length)],
    quantity: qty,
    unit_price: unitPrice,
    total_amount: parseFloat((qty * unitPrice).toFixed(2)),
    region: regions[Math.floor(Math.random() * regions.length)],
    sales_rep: reps[Math.floor(Math.random() * reps.length)]
  });
}

return [{ json: { data: rows, count: rows.length } }];
